self.go_to_xy(150, -75)

tempo = 3

while True:
    if self.key_pressed("a"):
        self.change_x(-tempo)
    if self.key_pressed("d"):
        self.change_x(tempo)
    if self.key_pressed("s"):
        self.change_y(-tempo)
    if self.key_pressed("w"):
        self.change_y(tempo)

self.go_to_xy(-150, -50)

tempo = 3

x_grenze = 210
y_grenze = 145

while True:
    if self.key_pressed("ArrowLeft") and self.x_position > -x_grenze:
        self.change_x(-tempo)
    if self.key_pressed("ArrowRight") and self.x_position < x_grenze:
        self.change_x(tempo)
    if self.key_pressed("ArrowDown") and self.y_position > -y_grenze:
        self.change_y(-tempo)
    if self.key_pressed("ArrowUp") and self.y_position < y_grenze:
        self.change_y(tempo)

self.go_to_xy(0, 75)

tempo = 3

x_grenze = 200
y_grenze = 140

x_geschw = 0
y_geschw = 0

beschl = 0.5

while True:
    if self.key_pressed("j"):
        x_geschw -= beschl
        x_geschw = max(x_geschw, -tempo)
    if self.key_pressed("l"):
        x_geschw += beschl
        x_geschw = min(x_geschw, tempo)
    if not self.key_pressed("j") and not self.key_pressed("l"):
        if x_geschw > 0:
            x_geschw -= beschl
        elif x_geschw < 0:
            x_geschw += beschl

    self.change_x(x_geschw)
    self.set_x(min(x_grenze, self.x_position))
    self.set_x(max(-x_grenze, self.x_position))

    if self.key_pressed("k"):
        y_geschw -= beschl
        y_geschw = max(y_geschw, -tempo)
    if self.key_pressed("i"):
        y_geschw += beschl
        y_geschw = min(y_geschw, tempo)
    if not self.key_pressed("k") and not self.key_pressed("i"):
        if y_geschw > 0:
            y_geschw -= beschl
        elif y_geschw < 0:
            y_geschw += beschl

    self.change_y(y_geschw)
    self.set_y(min(y_grenze, self.y_position))
    self.set_y(max(-y_grenze, self.y_position))
